// src/components/StreaksAchievements.jsx

import React, { useMemo } from "react";
import { ROLE_THEMES } from "./roleThemes";
import { useAppData } from "./AppDataContext";

export default function StreaksAchievements({ role = "all" }) {
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;
  const { workoutHistory = [] } = useAppData() || {};

  // Extract days with at least one workout
  const days = useMemo(() => {
    if (!Array.isArray(workoutHistory)) return [];
    return workoutHistory.map(d => d.date).sort();
  }, [workoutHistory]);

  // Calculate current streak (consecutive days up to today)
  const today = new Date().toISOString().split("T")[0];
  let streak = 0;
  let bestStreak = 0;
  let prev = null;
  days.forEach(date => {
    if (!prev) {
      streak = 1;
      bestStreak = 1;
      prev = date;
      return;
    }
    const prevDate = new Date(prev);
    const currDate = new Date(date);
    const diff = (currDate - prevDate) / (1000 * 60 * 60 * 24);
    if (diff === 1) {
      streak++;
    } else {
      bestStreak = Math.max(bestStreak, streak);
      streak = 1;
    }
    prev = date;
  });
  bestStreak = Math.max(bestStreak, streak);

  return (
    <div style={{
      minWidth: 0, width: "100%", flex: 1, padding: 0,
      color: "#fff", fontFamily: "'Oswald','Roboto Mono',sans-serif", background: "none", border: "none", boxShadow: "none"
    }}>
      <div style={{
        color: theme.thinLine, fontWeight: 900, fontSize: 22,
        letterSpacing: ".09em", marginBottom: 10, textAlign: "center"
      }}>
      </div>
      <div style={{ color: theme.accent, fontSize: 20, fontWeight: 800, textAlign: "center" }}>
        🔥 Current Streak: <span style={{ color: "#fff" }}>{streak} day{streak !== 1 ? "s" : ""}</span>
      </div>
      <div style={{
        color: theme.accent, fontWeight: 700, fontSize: 16, margin: "10px 0 8px 0", textAlign: "center"
      }}>
        🏆 Best Streak: <span style={{ color: "#fff" }}>{bestStreak} day{bestStreak !== 1 ? "s" : ""}</span>
        <br />
        Total workout days: <span style={{ color: "#fff" }}>{days.length}</span>
      </div>
      <div style={{
        fontSize: 13, color: "#aaa", fontWeight: 600, marginTop: 8, textAlign: "center"
      }}>
        How it works: <br />
        A streak is the number of consecutive days you’ve logged at least one workout.
        Missing a day breaks your streak. Keep it going!
      </div>
    </div>
  );
}
