// src/components/WaterProgressBar.jsx
import React, { useEffect, useState } from "react";
import { ROLE_THEMES } from "./roleThemes";
import { useAppData } from "./AppDataContext";

function loadGoal() {
  try {
    const raw = localStorage.getItem("water_goal");
    return raw ? Number(raw) : 100;
  } catch {
    return 100;
  }
}

export default function WaterProgressBar({ role = "all" }) {
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;
  const { water } = useAppData() || {};
  const [goal, setGoal] = useState(() => loadGoal());

  useEffect(() => {
    const onStorage = () => setGoal(loadGoal());
    window.addEventListener("storage", onStorage);
    return () => window.removeEventListener("storage", onStorage);
  }, []);

  const pct = Math.min(100, Math.round(((water ?? 0) / (goal || 1)) * 100));
  return (
    <div style={{
      background: "#181d21",
      borderRadius: 7,
      height: 18,
      margin: "8px 0 16px 0",
      position: "relative",
      border: `2px solid ${theme.thinLine}`,
      maxWidth: 320,
      marginLeft: "auto",
      marginRight: "auto"
    }}>
      <div style={{
        width: `${pct}%`,
        height: "100%",
        background: theme.accent,
        borderRadius: 7,
        transition: "width 0.3s"
      }}></div>
      <div style={{
        position: "absolute",
        top: 0, left: 0, width: "100%", height: "100%",
        color: "#fff",
        fontWeight: 800,
        fontSize: 13,
        textAlign: "center",
        lineHeight: "18px",
        textShadow: "0 1px 5px #000b"
      }}>
        {isNaN(pct) ? "—" : `${pct}% of goal`}
      </div>
    </div>
  );
}
