// src/components/WeightliftingLog.jsx

import React, { useState } from "react";
import { ROLE_THEMES } from "./roleThemes";
import { useAppData } from "./AppDataContext";
import WORKOUTS from "./workout";

export default function WeightliftingLog({ role = "all" }) {
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;
  const { weightLifts, setWeightLifts } = useAppData() || {};
  const [input, setInput] = useState({ workout: "", weight: "", reps: "", sets: "" });
  const [message, setMessage] = useState("");

  function handleChange(e) {
    const { name, value } = e.target;
    setInput(prev => ({
      ...prev,
      [name]: value.replace(/[^0-9a-zA-Z \-_]/g, "")
    }));
  }

  function handleAdd(e) {
    e.preventDefault();
    if (!input.workout || !input.weight || !input.reps || !input.sets) {
      setMessage("Fill out all fields.");
      setTimeout(() => setMessage(""), 1200);
      return;
    }
    const entry = {
      workout: input.workout,
      weight: Number(input.weight),
      reps: Number(input.reps),
      sets: Number(input.sets)
    };
    setWeightLifts((prev = []) => [...prev, entry]);
    setMessage("Entry added!");
    setInput({ workout: "", weight: "", reps: "", sets: "" });
    setTimeout(() => setMessage(""), 1200);
  }

  function handleReset() {
    setWeightLifts([]);
    setMessage("Log reset.");
    setTimeout(() => setMessage(""), 1200);
  }

  return (
    <div style={{
      minWidth: 0, width: "100%", flex: 1, padding: 0, color: "#fff", fontFamily: "'Oswald','Roboto Mono',sans-serif", background: "none", border: "none", boxShadow: "none"
    }}>
      <div style={{
        color: theme.thinLine, fontWeight: 900, fontSize: 24,
        letterSpacing: ".09em", marginBottom: 9, textAlign: "center"
      }}>
      </div>
      <form onSubmit={handleAdd} style={{ marginBottom: 12 }}>
        <div style={{
          display: "flex", gap: 7, alignItems: "center", marginBottom: 8, flexWrap: "wrap", justifyContent: "center"
        }}>
          <select
            name="workout"
            value={input.workout}
            onChange={handleChange}
            style={{
              width: 180, borderRadius: 6, border: `2px solid ${theme.thinLine}`,
              background: "#181d21", color: "#fff", fontWeight: 700,
              fontSize: 17, padding: "4px 7px"
            }}
          >
            <option value="">Select workout</option>
            {WORKOUTS.map(w =>
              <option key={w.name} value={w.name}>{w.name}</option>
            )}
          </select>
          <input
            name="weight"
            type="number"
            min={0}
            placeholder="Weight (lbs)"
            value={input.weight}
            onChange={handleChange}
            style={{
              width: 85, borderRadius: 6, border: `2px solid ${theme.thinLine}`,
              background: "#181d21", color: "#fff", fontWeight: 700,
              fontSize: 16, padding: "4px 7px", textAlign: "right"
            }}
            required
          />
          <input
            name="reps"
            type="number"
            min={0}
            placeholder="Reps"
            value={input.reps}
            onChange={handleChange}
            style={{
              width: 60, borderRadius: 6, border: `2px solid ${theme.thinLine}`,
              background: "#181d21", color: "#fff", fontWeight: 700,
              fontSize: 16, padding: "4px 7px", textAlign: "right"
            }}
            required
          />
          <input
            name="sets"
            type="number"
            min={0}
            placeholder="Sets"
            value={input.sets}
            onChange={handleChange}
            style={{
              width: 60, borderRadius: 6, border: `2px solid ${theme.thinLine}`,
              background: "#181d21", color: "#fff", fontWeight: 700,
              fontSize: 16, padding: "4px 7px", textAlign: "right"
            }}
            required
          />
          <button type="submit"
            style={{
              border: "none", borderRadius: 8, background: theme.thinLine,
              color: "#181d21", fontWeight: 900, fontSize: 16,
              padding: "6px 22px", cursor: "pointer"
            }}>
            Add Entry
          </button>
          <button type="button" onClick={handleReset}
            style={{
              border: "none", borderRadius: 8, background: "#e84444",
              color: "#fff", fontWeight: 900, fontSize: 16,
              padding: "6px 18px", cursor: "pointer"
            }}>
            Reset Log
          </button>
        </div>
        {message && <div style={{
          color: theme.thinLine, fontWeight: 800, marginTop: 5, textAlign: "center"
        }}>{message}</div>}
      </form>
      <div style={{
        color: theme.accent, fontWeight: 900, fontSize: 16,
        marginBottom: 6, marginTop: 18, textAlign: "center"
      }}>
        Today's Lifts
      </div>
      {(weightLifts && weightLifts.length > 0) ? (
        <table style={{
          width: "100%", color: "#fff", fontSize: 15, fontWeight: 700,
          borderSpacing: 0
        }}>
          <thead>
            <tr style={{ color: theme.accent }}>
              <th>Workout</th><th>Weight (lbs)</th><th>Reps</th><th>Sets</th>
            </tr>
          </thead>
          <tbody>
            {weightLifts.map((entry, i) => (
              <tr key={i}>
                <td>{entry.workout}</td>
                <td>{entry.weight}</td>
                <td>{entry.reps}</td>
                <td>{entry.sets}</td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <div style={{ color: "#aaa", textAlign: "center", fontWeight: 600, marginTop: 16 }}>
          No lifts logged yet today.
        </div>
      )}
    </div>
  );
}
