import React from "react";

export default function SplashScreen() {
  return (
    <div style={{
      minHeight: "100vh",
      width: "100vw",
      background: "linear-gradient(120deg, #1a223d 55%, #ff5400 100%)",
      display: "flex",
      alignItems: "center",
      justifyContent: "center"
    }}>
      <div style={{ textAlign: "center" }}>
        <img src={require("../assets/all_badge.png")} alt="ShiftStrong" style={{ width: 120, marginBottom: 30, filter: "drop-shadow(0 2px 20px #0008)" }} />
        <h1 style={{ color: "#fff", fontSize: 54, fontWeight: 900, letterSpacing: ".06em", margin: 0 }}>
          SHIFT<span style={{ color: "#ff5400" }}>STRONG</span>
        </h1>
        <div style={{ color: "#f2f2f2", fontSize: 24, marginTop: 24, letterSpacing: ".09em" }}>
          Serve strong. Stand together.<br />Tactical fitness for every responder.
        </div>
      </div>
    </div>
  );
}
