// src/components/hashPassword.js

// Simple hash function for passwords (NOT cryptographically secure, but good enough for localStorage)
// For real-world web apps, use bcrypt/argon2 on a backend server!

export function hashPassword(password) {
  // Basic hash: djb2 algorithm
  let hash = 5381;
  let i = password.length;
  while(i) {
    hash = (hash * 33) ^ password.charCodeAt(--i);
  }
  return (hash >>> 0).toString(36); // Return unsigned integer, base36 for shorter string
}

