// src/components/MacroGoalWidget.jsx
import React, { useState, useEffect } from "react";
import { ROLE_THEMES } from "./roleThemes";

const DEFAULT_GOALS = { protein: 150, carbs: 200, fat: 60, fiber: 25 };

function loadGoals() {
  try {
    const raw = localStorage.getItem("macro_goals");
    return raw ? JSON.parse(raw) : { ...DEFAULT_GOALS };
  } catch {
    return { ...DEFAULT_GOALS };
  }
}
function saveGoals(goals) {
  localStorage.setItem("macro_goals", JSON.stringify(goals));
}

export default function MacroGoalWidget({ role = "all" }) {
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;
  const [goals, setGoals] = useState(() => loadGoals());
  const [message, setMessage] = useState("");

  useEffect(() => { saveGoals(goals); }, [goals]);

  function handleChange(e) {
    const { name, value } = e.target;
    setGoals(prev => ({ ...prev, [name]: value.replace(/[^0-9]/g, "") }));
  }

  function handleSave(e) {
    e.preventDefault();
    setMessage("Goals saved!");
    setTimeout(() => setMessage(""), 1200);
  }

  return (
    <div style={{
      background: theme.widgetBg,
      border: `3.5px solid ${theme.thinLine}`,
      borderRadius: 14,
      color: "#fff",
      padding: 20,
      minWidth: 260,
      maxWidth: 320,
      margin: "0 auto",
      marginBottom: 18,
      boxShadow: "0 2px 10px #0006"
    }}>
      <div style={{
        fontWeight: 900,
        fontSize: 22,
        color: theme.thinLine,
        letterSpacing: ".10em",
        marginBottom: 7,
        textAlign: "center"
      }}>
        Macro Goals
      </div>
      <form onSubmit={handleSave}>
        <table style={{ width: "100%", fontSize: 18, fontWeight: 700 }}>
          <tbody>
            <tr>
              <td style={{ color: theme.accent }}>Protein:</td>
              <td>
                <input
                  name="protein"
                  type="number"
                  value={goals.protein}
                  onChange={handleChange}
                  style={{
                    width: 60,
                    borderRadius: 5,
                    border: `2px solid ${theme.thinLine}`,
                    background: "#181d21",
                    color: "#fff",
                    fontWeight: 700,
                    fontSize: 17,
                    padding: "2px 5px",
                    textAlign: "right"
                  }}
                /> g
              </td>
            </tr>
            <tr>
              <td style={{ color: theme.accent }}>Carbs:</td>
              <td>
                <input
                  name="carbs"
                  type="number"
                  value={goals.carbs}
                  onChange={handleChange}
                  style={{
                    width: 60,
                    borderRadius: 5,
                    border: `2px solid ${theme.thinLine}`,
                    background: "#181d21",
                    color: "#fff",
                    fontWeight: 700,
                    fontSize: 17,
                    padding: "2px 5px",
                    textAlign: "right"
                  }}
                /> g
              </td>
            </tr>
            <tr>
              <td style={{ color: theme.accent }}>Fat:</td>
              <td>
                <input
                  name="fat"
                  type="number"
                  value={goals.fat}
                  onChange={handleChange}
                  style={{
                    width: 60,
                    borderRadius: 5,
                    border: `2px solid ${theme.thinLine}`,
                    background: "#181d21",
                    color: "#fff",
                    fontWeight: 700,
                    fontSize: 17,
                    padding: "2px 5px",
                    textAlign: "right"
                  }}
                /> g
              </td>
            </tr>
            <tr>
              <td style={{ color: theme.accent }}>Fiber:</td>
              <td>
                <input
                  name="fiber"
                  type="number"
                  value={goals.fiber}
                  onChange={handleChange}
                  style={{
                    width: 60,
                    borderRadius: 5,
                    border: `2px solid ${theme.thinLine}`,
                    background: "#181d21",
                    color: "#fff",
                    fontWeight: 700,
                    fontSize: 17,
                    padding: "2px 5px",
                    textAlign: "right"
                  }}
                /> g
              </td>
            </tr>
          </tbody>
        </table>
        <button type="submit"
          style={{
            marginTop: 10,
            padding: "8px 0",
            width: "100%",
            borderRadius: 7,
            background: theme.thinLine,
            color: "#181d21",
            border: "none",
            fontWeight: 900,
            fontSize: 16,
            cursor: "pointer"
          }}>
          Save Goals
        </button>
        {message && <div style={{
          color: theme.thinLine,
          textAlign: "center",
          fontWeight: 800,
          marginTop: 8
        }}>{message}</div>}
      </form>
    </div>
  );
}
