// src/components/GoalSetting.jsx

import React, { useState, useEffect } from "react";
import { ROLE_THEMES } from "./roleThemes";
import { useAppData } from "./AppDataContext";

const PRESET_GOALS = [
  { name: "Bench Press", label: "Bench 225 lbs", target: 225 },
  { name: "Squat", label: "Squat 500 lbs", target: 500 },
  { name: "Deadlift", label: "Deadlift 600 lbs", target: 600 },
  { name: "Pull-Up", label: "20 Pull-Ups", target: 20 },
  { name: "Run Mile", label: "Mile in 6:00", target: 6 },
  { name: "Push-Ups", label: "100 Push-Ups", target: 100 },
  // Add more as you like
];

function loadGoals() {
  try {
    const raw = localStorage.getItem("user_goals");
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}
function saveGoals(goals) {
  localStorage.setItem("user_goals", JSON.stringify(goals));
}

export default function GoalSetting({ role = "all" }) {
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;
  const { weightLifts = [] } = useAppData() || {};
  const [goals, setGoals] = useState(() => loadGoals());
  const [preset, setPreset] = useState("");
  const [target, setTarget] = useState("");
  const [message, setMessage] = useState("");

  useEffect(() => { saveGoals(goals); }, [goals]);

  function handleAddGoal(e) {
    e.preventDefault();
    if (!preset || !target) return;
    setGoals(g => [...g, { preset, target: Number(target) }]);
    setMessage("Goal added!");
    setPreset(""); setTarget("");
    setTimeout(() => setMessage(""), 1100);
  }
  function handleResetGoals() {
    setGoals([]);
    setMessage("Goals reset.");
    setTimeout(() => setMessage(""), 1100);
  }

  // For each goal, find progress (sample: from weightLifts)
  function getProgress(goal) {
    const match = Array.isArray(weightLifts)
      ? weightLifts.filter(l => l.workout === goal.preset)
      : [];
    const maxVal = match.length > 0
      ? Math.max(...match.map(l => l.weight || 0))
      : 0;
    return { progress: maxVal, percent: Math.min(100, Math.round((maxVal / goal.target) * 100)) };
  }

  return (
    <div style={{
      minWidth: 0, width: "100%", flex: 1, padding: 0,
      color: "#fff", fontFamily: "'Oswald','Roboto Mono',sans-serif", background: "none", border: "none", boxShadow: "none"
    }}>
      <div style={{
        color: theme.thinLine, fontWeight: 900, fontSize: 22,
        letterSpacing: ".09em", marginBottom: 8, textAlign: "center"
      }}>
        Goals
      </div>
      <form onSubmit={handleAddGoal} style={{ display: "flex", gap: 7, marginBottom: 12, alignItems: "center", justifyContent: "center" }}>
        <select
          value={preset}
          onChange={e => setPreset(e.target.value)}
          style={{
            borderRadius: 8, border: `2px solid ${theme.thinLine}`,
            background: "#181d21", color: "#fff", fontWeight: 700, fontSize: 17, padding: "6px 16px"
          }}
        >
          <option value="">Select...</option>
          {PRESET_GOALS.map(g =>
            <option key={g.name} value={g.name}>{g.label}</option>
          )}
        </select>
        <input
          type="number"
          placeholder="Target"
          value={target}
          onChange={e => setTarget(e.target.value.replace(/[^0-9]/g, ""))}
          style={{
            width: 70, borderRadius: 6, border: `2px solid ${theme.thinLine}`,
            background: "#181d21", color: "#fff", fontWeight: 700, fontSize: 17, padding: "4px 7px", textAlign: "right"
          }}
          required
        />
        <button type="submit"
          style={{
            border: "none", borderRadius: 8, background: theme.thinLine,
            color: "#181d21", fontWeight: 900, fontSize: 16,
            padding: "6px 16px", cursor: "pointer"
          }}>
          Add Goal
        </button>
        <button type="button" onClick={handleResetGoals}
          style={{
            border: "none", borderRadius: 8, background: "#e84444",
            color: "#fff", fontWeight: 900, fontSize: 16,
            padding: "6px 16px", cursor: "pointer"
          }}>
          Reset All
        </button>
      </form>
      <div style={{ fontWeight: 700, color: theme.accent, marginBottom: 4, fontSize: 17 }}>Your Goals</div>
      {goals.length === 0 && (
        <div style={{ color: "#aaa", fontWeight: 600 }}>No goals set yet.</div>
      )}
      {goals.map((goal, idx) => {
        const progress = getProgress(goal);
        return (
          <div key={idx} style={{
            marginBottom: 8, color: "#fff", fontWeight: 600, fontSize: 15
          }}>
            {goal.preset} – Target: {goal.target} <br />
            <span style={{ color: theme.accent }}>
              Progress: {progress.progress} / {goal.target} ({progress.percent}%)
            </span>
            <div style={{
              width: "100%", background: "#181d21", height: 10, borderRadius: 5, marginTop: 3,
              marginBottom: 2, position: "relative", overflow: "hidden"
            }}>
              <div style={{
                width: `${progress.percent}%`, height: "100%", background: theme.accent, borderRadius: 5
              }}></div>
            </div>
          </div>
        );
      })}
      {message && <div style={{ color: theme.thinLine, fontWeight: 800, marginTop: 6 }}>{message}</div>}
    </div>
  );
}
