// src/components/MacroTotalWidget.jsx
import React from "react";
import { ROLE_THEMES } from "./roleThemes";
import { useAppData } from "./AppDataContext";

export default function MacroTotalWidget({ role = "all" }) {
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;
  const { macros } = useAppData() || {};
  const totals = {
    protein: macros?.protein || 0,
    carbs: macros?.carbs || 0,
    fat: macros?.fat || 0,
    fiber: macros?.fiber || 0
  };

  return (
    <div style={{
      background: theme.widgetBg,
      border: `3.5px solid ${theme.thinLine}`,
      borderRadius: 14,
      color: "#fff",
      padding: 20,
      minWidth: 260,
      maxWidth: 320,
      margin: "0 auto",
      marginBottom: 18,
      boxShadow: "0 2px 10px #0006"
    }}>
      <div style={{
        fontWeight: 900,
        fontSize: 22,
        color: theme.thinLine,
        letterSpacing: ".10em",
        marginBottom: 7,
        textAlign: "center"
      }}>
        Today's Macros
      </div>
      <table style={{ width: "100%", fontSize: 18, fontWeight: 700 }}>
        <tbody>
          <tr>
            <td style={{ color: theme.accent }}>Protein:</td>
            <td style={{ textAlign: "right" }}>{totals.protein} g</td>
          </tr>
          <tr>
            <td style={{ color: theme.accent }}>Carbs:</td>
            <td style={{ textAlign: "right" }}>{totals.carbs} g</td>
          </tr>
          <tr>
            <td style={{ color: theme.accent }}>Fat:</td>
            <td style={{ textAlign: "right" }}>{totals.fat} g</td>
          </tr>
          <tr>
            <td style={{ color: theme.accent }}>Fiber:</td>
            <td style={{ textAlign: "right" }}>{totals.fiber} g</td>
          </tr>
        </tbody>
      </table>
    </div>
  );
}
