// src/components/MacroTracker.jsx

import React, { useState, useEffect } from "react";
import { ROLE_THEMES } from "./roleThemes";
import { useAppData } from "./AppDataContext";
import MacroTotalWidget from "./MacroTotalWidget";
import MacroGoalWidget from "./MacroGoalWidget";

export default function MacroTracker({ role = "all" }) {
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;
  const { macros, setMacros } = useAppData() || {};
  const [input, setInput] = useState({ protein: "", carbs: "", fat: "", fiber: "" });
  const [message, setMessage] = useState("");

  useEffect(() => {
    if (macros) setInput({
      protein: macros.protein || "",
      carbs: macros.carbs || "",
      fat: macros.fat || "",
      fiber: macros.fiber || ""
    });
  }, [macros]);

  function handleChange(e) {
    const { name, value } = e.target;
    setInput(prev => ({
      ...prev,
      [name]: value.replace(/[^0-9]/g, "")
    }));
  }

  function handleSave(e) {
    e.preventDefault();
    setMacros({
      protein: input.protein ? Number(input.protein) : 0,
      carbs: input.carbs ? Number(input.carbs) : 0,
      fat: input.fat ? Number(input.fat) : 0,
      fiber: input.fiber ? Number(input.fiber) : 0
    });
    setMessage("Macros saved!");
    setTimeout(() => setMessage(""), 1300);
  }

  function handleReset() {
    setInput({ protein: "", carbs: "", fat: "", fiber: "" });
    setMacros({ protein: 0, carbs: 0, fat: 0, fiber: 0 });
    setMessage("Macros reset.");
    setTimeout(() => setMessage(""), 1300);
  }

  return (
    <div style={{
      minWidth: 0, width: "100%", flex: 1, padding: 0, color: "#fff",
      fontFamily: "'Oswald','Roboto Mono',sans-serif", background: "none", border: "none", boxShadow: "none"
    }}>
      <div style={{
        color: theme.thinLine, fontWeight: 900, fontSize: 22,
        letterSpacing: ".09em", marginBottom: 9, textAlign: "center"
      }}>
      </div>
      <div style={{
        display: "flex", gap: 10, justifyContent: "center", alignItems: "center", flexWrap: "wrap", marginBottom: 10
      }}>
        <MacroTotalWidget role={role} />
        <MacroGoalWidget role={role} />
      </div>
      <form onSubmit={handleSave} style={{ width: "100%", marginTop: 0 }}>
        <div style={{
          display: "flex", gap: 8, alignItems: "center", justifyContent: "center", flexWrap: "wrap", marginBottom: 6
        }}>
          {["protein", "carbs", "fat", "fiber"].map(macro => (
            <div key={macro} style={{
              display: "flex", alignItems: "center", gap: 4, flexDirection: "column", minWidth: 72, maxWidth: 84
            }}>
              <label style={{ color: theme.accent, fontWeight: 700, fontSize: 14, textTransform: "capitalize" }}>
                {macro}<span style={{ color: "#999", fontSize: 12 }}> (g)</span>
              </label>
              <input
                name={macro}
                type="number"
                min="0"
                value={input[macro]}
                onChange={handleChange}
                style={{
                  width: 55,
                  borderRadius: 6,
                  border: `2px solid ${theme.thinLine}`,
                  background: "#181d21",
                  color: "#fff",
                  fontWeight: 700,
                  fontSize: 15,
                  padding: "4px 4px",
                  textAlign: "center"
                }}
                required
              />
            </div>
          ))}
        </div>
        <div style={{
          display: "flex", gap: 10, marginTop: 7, justifyContent: "center", flexWrap: "wrap"
        }}>
          <button type="submit"
            style={{
              padding: "8px 0", borderRadius: 8, fontSize: 15, fontWeight: 900,
              background: theme.thinLine, color: "#181d21", border: "none", cursor: "pointer", width: 90
            }}>
            Save
          </button>
          <button type="button" onClick={handleReset}
            style={{
              padding: "8px 0", borderRadius: 8, fontSize: 15, fontWeight: 900,
              background: "#e84444", color: "#fff", border: "none", cursor: "pointer", width: 90
            }}>
            Reset
          </button>
        </div>
        {message && <div style={{
          color: theme.thinLine, fontWeight: 800, marginTop: 8, textAlign: "center"
        }}>{message}</div>}
      </form>
    </div>
  );
}
