import React, { createContext, useContext, useState, useEffect } from "react";

// ---- App Data Context for all widgets ----
export const AppDataContext = createContext();

export function AppDataProvider({ children, user }) {
  // Keyed by user and date for multi-user support
  const storageKey = user?.name ? `shiftstrong_${user.name}` : "shiftstrong_guest";

  // Helper: today's ISO date string
  function todayStr() {
    return new Date().toISOString().split("T")[0];
  }

  // Load/save state from localStorage
  function loadData() {
    try {
      const raw = localStorage.getItem(storageKey);
      return raw ? JSON.parse(raw) : {};
    } catch {
      return {};
    }
  }
  function saveData(data) {
    localStorage.setItem(storageKey, JSON.stringify(data));
  }

  // ---- State ----
  const [data, setData] = useState(() => loadData());

  // Live today/date keys for per-day data
  const currentDate = todayStr();

  // ---- State Setters and Updaters ----
  function logWorkout(entry) {
    setData(prev => {
      const copy = { ...prev };
      copy.workouts = copy.workouts || {};
      copy.workouts[currentDate] = (copy.workouts[currentDate] || []).concat([entry]);
      // PR auto-update
      copy.prHistory = calcPRHistory(copy.workouts);
      // Workout days for streaks
      copy.workoutDays = Object.keys(copy.workouts).filter(d => copy.workouts[d]?.length > 0);
      saveData(copy);
      return copy;
    });
  }

  function logPR(prEntry) {
    setData(prev => {
      const copy = { ...prev };
      copy.prHistory = (copy.prHistory || []).concat([prEntry]);
      saveData(copy);
      return copy;
    });
  }

  function setMacros(macros) {
    setData(prev => {
      const copy = { ...prev };
      copy.macros = copy.macros || {};
      copy.macros[currentDate] = macros;
      saveData(copy);
      return copy;
    });
  }

  function setWater(amount) {
    setData(prev => {
      const copy = { ...prev };
      copy.water = copy.water || {};
      copy.water[currentDate] = amount;
      saveData(copy);
      return copy;
    });
  }

  function setGoals(goals) {
    setData(prev => {
      const copy = { ...prev };
      copy.goals = goals;
      saveData(copy);
      return copy;
    });
  }

  // Daily reset: clears only per-day data at midnight
  useEffect(() => {
    const timer = setInterval(() => {
      const stored = loadData();
      const newDate = todayStr();
      // If date changed, ensure today has empty values for macros/water/workouts if not present
      let changed = false;
      if (!stored.macros) stored.macros = {};
      if (!stored.macros[newDate]) { stored.macros[newDate] = { protein: "", carbs: "", fat: "", fiber: "" }; changed = true; }
      if (!stored.water) stored.water = {};
      if (!stored.water[newDate]) { stored.water[newDate] = 0; changed = true; }
      if (!stored.workouts) stored.workouts = {};
      if (!stored.workouts[newDate]) { stored.workouts[newDate] = []; changed = true; }
      if (changed) {
        saveData(stored);
        setData({ ...stored });
      }
    }, 60 * 1000);
    return () => clearInterval(timer);
    // eslint-disable-next-line
  }, []);

  // ---- Helper: Calculate PR history from all workouts ----
  function calcPRHistory(allWorkouts = {}) {
    let history = [];
    Object.entries(allWorkouts).forEach(([date, entries]) => {
      entries.forEach(entry => {
        // Example: PR is heaviest bench, squat, or whatever
        history.push({ date, pr: Number(entry.weight || 0) });
      });
    });
    // Reduce to one PR per day (main lift, for simplicity)
    return history.sort((a, b) => a.date.localeCompare(b.date));
  }

  // ---- Output, for use in all widgets ----
  const value = {
    // Data accessors
    macros: data.macros?.[currentDate] || { protein: "", carbs: "", fat: "", fiber: "" },
    water: data.water?.[currentDate] ?? 0,
    workoutsToday: data.workouts?.[currentDate] || [],
    workoutHistory: Object.entries(data.workouts || {}).map(([date, entries]) => ({
      date, totalWeight: entries.reduce((sum, e) => sum + (Number(e.weight) * Number(e.reps || 1) * Number(e.sets || 1)), 0)
    })),
    prHistory: data.prHistory || [],
    goals: data.goals || [],
    workoutDays: data.workoutDays || [],
    // Actions
    logWorkout,
    logPR,
    setMacros,
    setWater,
    setGoals
  };

  return (
    <AppDataContext.Provider value={value}>
      {children}
    </AppDataContext.Provider>
  );
}

// Custom hook for easier access
export function useAppData() {
  return useContext(AppDataContext);
}
