// src/components/WorkoutDescriptions.jsx

import React, { useState } from "react";
import { ROLE_THEMES } from "./roleThemes";
import WORKOUTS from "./workout"; // See below for a robust example workout.js

// Muscle groups for dropdown
const MUSCLE_GROUPS = [
  "Chest", "Back", "Shoulders", "Triceps", "Biceps", "Legs", "Core", "Glutes", "Calves", "Forearms", "Full Body", "Cardio", "Mobility"
];

export default function WorkoutDescriptions({ role = "all" }) {
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;
  const [muscle, setMuscle] = useState("");
  const [showAll, setShowAll] = useState(false);

  // Filter workouts by muscle group (case-insensitive, substring match)
  const filteredWorkouts = muscle
    ? WORKOUTS.filter(w =>
        w.muscleGroups.some(mg =>
          mg.toLowerCase().includes(muscle.toLowerCase())
        )
      )
    : [];

  return (
    <div style={{
      background: theme.widgetBg,
      border: `3.5px solid ${theme.thinLine}`,
      borderRadius: 16,
      color: "#fff",
      boxShadow: "0 2px 13px #0006",
      maxWidth: 700,
      margin: "30px auto",
      padding: "32px 30px 22px 30px",
      fontFamily: "'Oswald','Roboto Mono',sans-serif"
    }}>
      <div style={{
        color: theme.thinLine,
        fontWeight: 900,
        fontSize: 24,
        letterSpacing: ".09em",
        marginBottom: 14,
        textAlign: "center"
      }}>
        Workout Descriptions
      </div>
      <div style={{ marginBottom: 18, display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center" }}>
        <label style={{ fontWeight: 700, color: theme.accent, fontSize: 18 }}>
          Select Muscle Group:
        </label>
        <select
          value={muscle}
          onChange={e => setMuscle(e.target.value)}
          style={{
            borderRadius: 8,
            border: `2px solid ${theme.thinLine}`,
            background: "#181d21",
            color: "#fff",
            fontWeight: 700,
            fontSize: 17,
            padding: "6px 16px"
          }}
        >
          <option value="">-- Choose --</option>
          {MUSCLE_GROUPS.map(mg =>
            <option key={mg} value={mg}>{mg}</option>
          )}
        </select>
        {muscle && (
          <button
            onClick={() => setMuscle("")}
            style={{
              marginLeft: 12,
              border: "none",
              background: theme.thinLine,
              color: "#181d21",
              fontWeight: 900,
              borderRadius: 8,
              padding: "6px 22px",
              fontSize: 16,
              cursor: "pointer"
            }}
          >Clear</button>
        )}
      </div>
      {!muscle && (
        <div style={{
          color: "#aaa",
          textAlign: "center",
          fontWeight: 700,
          margin: "40px 0 18px 0",
          fontSize: 18
        }}>
          <span>Select a muscle group above to view targeted workouts.</span>
        </div>
      )}
      {muscle && filteredWorkouts.length === 0 && (
        <div style={{
          color: "#e84444",
          textAlign: "center",
          fontWeight: 800,
          margin: "30px 0 18px 0",
          fontSize: 18
        }}>
          No workouts found for {muscle}.
        </div>
      )}
      {muscle && filteredWorkouts.length > 0 && (
        <div style={{ marginTop: 16 }}>
          {filteredWorkouts.map(w => (
            <div key={w.name} style={{
              background: "#15181a",
              borderRadius: 11,
              border: `2px solid ${theme.thinLine}`,
              margin: "0 0 16px 0",
              padding: "13px 18px"
            }}>
              <div style={{ color: theme.accent, fontWeight: 800, fontSize: 19, marginBottom: 4 }}>
                {w.name}
                <span style={{ color: "#999", fontWeight: 500, fontSize: 15, marginLeft: 7 }}>
                  [{w.muscleGroups.join(", ")}]
                </span>
              </div>
              <div style={{
                color: "#ddd",
                fontWeight: 600,
                fontSize: 16,
                marginBottom: 4
              }}>
                {w.description}
              </div>
              <div style={{
                color: "#aaa",
                fontSize: 15,
                marginTop: 2
              }}>
                <b>How-to:</b> {w.howTo}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

