// src/components/Login.jsx

import React, { useState } from "react";
import tacticalBg from "../assets/tactical_login_bg.png";
import { hashPassword } from "./hashPassword";
import { ROLE_THEMES, ROLES } from "./roleThemes";

function loadAccounts() {
  try {
    const raw = localStorage.getItem("shiftstrongAccounts");
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}
function saveAccounts(accounts) {
  localStorage.setItem("shiftstrongAccounts", JSON.stringify(accounts));
}

export default function Login({ onLogin }) {
  const [mode, setMode] = useState("login"); // login, register, forgot, reset, deleted
  const [name, setName] = useState("");
  const [role, setRole] = useState("");
  const [password, setPassword] = useState("");
  const [password2, setPassword2] = useState("");
  const [resetPassword, setResetPassword] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [deleteConfirm, setDeleteConfirm] = useState(false);

  // Used in forgot/reset password
  const [resetStep, setResetStep] = useState(0);

  function handleLogin(e) {
    e.preventDefault();
    const accounts = loadAccounts();
    const user = accounts.find(
      a => a.name.trim().toLowerCase() === name.trim().toLowerCase()
    );
    if (!user) {
      setError("Account not found.");
      return;
    }
    if (user.password !== hashPassword(password)) {
      setError("Incorrect password.");
      return;
    }
    setError("");
    setSuccess("Login successful!");
    setTimeout(() => {
      setSuccess("");
      onLogin({ name: user.name, role: user.role });
    }, 700);
  }

  function handleRegister(e) {
    e.preventDefault();
    if (!name.trim() || !role || !password || !password2) {
      setError("All fields required.");
      return;
    }
    if (password.length < 4) {
      setError("Password must be at least 4 characters.");
      return;
    }
    if (password !== password2) {
      setError("Passwords do not match.");
      return;
    }
    let accounts = loadAccounts();
    if (accounts.find(a => a.name.trim().toLowerCase() === name.trim().toLowerCase())) {
      setError("Account already exists.");
      return;
    }
    accounts.push({
      name: name.trim(),
      role,
      password: hashPassword(password)
    });
    saveAccounts(accounts);
    setError("");
    setSuccess("Account created! You can now log in.");
    setMode("login");
    setName(""); setRole(""); setPassword(""); setPassword2("");
    setTimeout(() => setSuccess(""), 1500);
  }

  function handleDelete() {
    if (!name.trim() || !password) {
      setError("Enter your name and password.");
      return;
    }
    let accounts = loadAccounts();
    const idx = accounts.findIndex(
      a => a.name.trim().toLowerCase() === name.trim().toLowerCase()
    );
    if (idx === -1) {
      setError("Account not found.");
      return;
    }
    if (accounts[idx].password !== hashPassword(password)) {
      setError("Incorrect password.");
      return;
    }
    accounts.splice(idx, 1);
    saveAccounts(accounts);
    setSuccess("Account deleted!");
    setName(""); setRole(""); setPassword(""); setPassword2(""); setError("");
    setDeleteConfirm(false);
    setTimeout(() => {
      setSuccess("");
      setMode("login");
    }, 1200);
  }

  function handleForgotStart(e) {
    e.preventDefault();
    if (!name.trim() || !role) {
      setError("Enter your name and role.");
      return;
    }
    let accounts = loadAccounts();
    const user = accounts.find(
      a =>
        a.name.trim().toLowerCase() === name.trim().toLowerCase() &&
        a.role === role
    );
    if (!user) {
      setError("No account with that name and role.");
      return;
    }
    setResetStep(1);
    setError("");
  }

  function handleForgotReset(e) {
    e.preventDefault();
    if (!resetPassword || resetPassword.length < 4) {
      setError("Password must be at least 4 characters.");
      return;
    }
    let accounts = loadAccounts();
    const idx = accounts.findIndex(
      a =>
        a.name.trim().toLowerCase() === name.trim().toLowerCase() &&
        a.role === role
    );
    if (idx === -1) {
      setError("No account with that name and role.");
      return;
    }
    accounts[idx].password = hashPassword(resetPassword);
    saveAccounts(accounts);
    setSuccess("Password reset! You can now log in.");
    setName(""); setRole(""); setPassword(""); setPassword2(""); setResetPassword(""); setError("");
    setResetStep(0);
    setTimeout(() => {
      setSuccess("");
      setMode("login");
    }, 1800);
  }

  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;

  // Reset all UI state on mode change
  function switchMode(next) {
    setMode(next);
    setName(""); setRole(""); setPassword(""); setPassword2(""); setError(""); setSuccess(""); setResetPassword("");
    setResetStep(0); setDeleteConfirm(false);
  }

  return (
    <div
      style={{
        minHeight: "100vh",
        width: "100vw",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: `url(${tacticalBg}) center center / cover no-repeat fixed`
      }}
    >
      <form
        style={{
          background: "#192232cc",
          borderRadius: 18,
          padding: 40,
          boxShadow: "0 6px 36px #111a",
          display: "flex",
          flexDirection: "column",
          gap: 22,
          minWidth: 340,
          border: `3px solid ${theme.thinLine}`
        }}
        onSubmit={
          mode === "login"
            ? handleLogin
            : mode === "register"
            ? handleRegister
            : mode === "forgot" && resetStep === 0
            ? handleForgotStart
            : mode === "forgot" && resetStep === 1
            ? handleForgotReset
            : e => e.preventDefault()
        }
      >
        <h2 style={{
          color: theme.accent,
          fontWeight: 900,
          letterSpacing: ".11em",
          textShadow: "0 1px 8px #000d"
        }}>
          {mode === "login"
            ? "Login"
            : mode === "register"
            ? "Register"
            : mode === "forgot"
            ? "Reset Password"
            : mode === "deleted"
            ? "Account Deleted"
            : ""}
        </h2>
        {error && (
          <div style={{
            background: "#e84444",
            color: "#fff",
            borderRadius: 6,
            padding: 7,
            textAlign: "center",
            fontWeight: "bold"
          }}>{error}</div>
        )}
        {success && (
          <div style={{
            background: "#b7ce63",
            color: "#111",
            borderRadius: 6,
            padding: 7,
            textAlign: "center",
            fontWeight: "bold"
          }}>{success}</div>
        )}

        {/* Login, Register, Forgot Password UI */}
        {(mode === "login" || mode === "register" || mode === "forgot") && (
          <>
            <input
              style={{
                padding: 10,
                borderRadius: 6,
                border: `2px solid ${theme.thinLine}`,
                fontSize: 17,
                fontWeight: 700,
                background: "#1a2135",
                color: "#fff"
              }}
              placeholder="Your Name"
              value={name}
              autoFocus
              onChange={e => setName(e.target.value)}
            />
            <select
              style={{
                padding: 10,
                borderRadius: 6,
                border: `2px solid ${theme.thinLine}`,
                fontSize: 17,
                fontWeight: 700,
                background: "#1a2135",
                color: theme.accent
              }}
              value={role}
              onChange={e => setRole(e.target.value)}
              required
            >
              <option value="">Select Your Occupation</option>
              {ROLES.map(r => (
                <option key={r} value={r}>{r[0].toUpperCase() + r.slice(1)}</option>
              ))}
            </select>
          </>
        )}

        {/* Login Password Field */}
        {mode === "login" && (
          <>
            <input
              style={{
                padding: 10,
                borderRadius: 6,
                border: `2px solid ${theme.thinLine}`,
                fontSize: 17,
                fontWeight: 700,
                background: "#1a2135",
                color: "#fff"
              }}
              placeholder="Password"
              type="password"
              autoComplete="current-password"
              value={password}
              onChange={e => setPassword(e.target.value)}
            />
            <button
              type="submit"
              style={{
                padding: "10px 0",
                borderRadius: 6,
                fontSize: 19,
                fontWeight: 900,
                letterSpacing: ".11em",
                background: theme.thinLine,
                color: "#181d21",
                border: "none",
                cursor: "pointer",
                marginTop: 8
              }}
            >
              Enter Dashboard
            </button>
            <div style={{ display: "flex", gap: 10, flexDirection: "column" }}>
              <button
                type="button"
                onClick={() => switchMode("register")}
                style={{
                  background: "none",
                  color: theme.thinLine,
                  border: "none",
                  fontWeight: 700,
                  cursor: "pointer",
                  textDecoration: "underline"
                }}
              >
                No account? Register
              </button>
              <button
                type="button"
                onClick={() => switchMode("forgot")}
                style={{
                  background: "none",
                  color: theme.thinLine,
                  border: "none",
                  fontWeight: 700,
                  cursor: "pointer",
                  textDecoration: "underline"
                }}
              >
                Forgot password?
              </button>
              <button
                type="button"
                onClick={() => setDeleteConfirm(true)}
                style={{
                  background: "none",
                  color: "#e84444",
                  border: "none",
                  fontWeight: 700,
                  cursor: "pointer",
                  textDecoration: "underline",
                  marginTop: 6
                }}
              >
                Delete my account
              </button>
            </div>
          </>
        )}

        {/* Register UI */}
        {mode === "register" && (
          <>
            <input
              style={{
                padding: 10,
                borderRadius: 6,
                border: `2px solid ${theme.thinLine}`,
                fontSize: 17,
                fontWeight: 700,
                background: "#1a2135",
                color: "#fff"
              }}
              placeholder="Password"
              type="password"
              autoComplete="new-password"
              value={password}
              onChange={e => setPassword(e.target.value)}
            />
            <input
              style={{
                padding: 10,
                borderRadius: 6,
                border: `2px solid ${theme.thinLine}`,
                fontSize: 17,
                fontWeight: 700,
                background: "#1a2135",
                color: "#fff"
              }}
              placeholder="Repeat Password"
              type="password"
              autoComplete="new-password"
              value={password2}
              onChange={e => setPassword2(e.target.value)}
            />
            <button
              type="submit"
              style={{
                padding: "10px 0",
                borderRadius: 6,
                fontSize: 19,
                fontWeight: 900,
                letterSpacing: ".11em",
                background: theme.thinLine,
                color: "#181d21",
                border: "none",
                cursor: "pointer",
                marginTop: 8
              }}
            >
              Register
            </button>
            <button
              type="button"
              onClick={() => switchMode("login")}
              style={{
                background: "none",
                color: theme.thinLine,
                border: "none",
                fontWeight: 700,
                cursor: "pointer",
                textDecoration: "underline"
              }}
            >
              Already have an account? Login
            </button>
          </>
        )}

        {/* Forgot Password */}
        {mode === "forgot" && (
          <>
            {resetStep === 0 && (
              <>
                <button
                  type="submit"
                  style={{
                    padding: "10px 0",
                    borderRadius: 6,
                    fontSize: 19,
                    fontWeight: 900,
                    letterSpacing: ".11em",
                    background: theme.thinLine,
                    color: "#181d21",
                    border: "none",
                    cursor: "pointer",
                    marginTop: 8
                  }}
                >
                  Next
                </button>
                <button
                  type="button"
                  onClick={() => switchMode("login")}
                  style={{
                    background: "none",
                    color: theme.thinLine,
                    border: "none",
                    fontWeight: 700,
                    cursor: "pointer",
                    textDecoration: "underline",
                    marginTop: 2
                  }}
                >
                  Back to Login
                </button>
              </>
            )}
            {resetStep === 1 && (
              <>
                <input
                  style={{
                    padding: 10,
                    borderRadius: 6,
                    border: `2px solid ${theme.thinLine}`,
                    fontSize: 17,
                    fontWeight: 700,
                    background: "#1a2135",
                    color: "#fff"
                  }}
                  placeholder="New Password"
                  type="password"
                  autoComplete="new-password"
                  value={resetPassword}
                  onChange={e => setResetPassword(e.target.value)}
                />
                <button
                  type="submit"
                  style={{
                    padding: "10px 0",
                    borderRadius: 6,
                    fontSize: 19,
                    fontWeight: 900,
                    letterSpacing: ".11em",
                    background: theme.thinLine,
                    color: "#181d21",
                    border: "none",
                    cursor: "pointer",
                    marginTop: 8
                  }}
                >
                  Reset Password
                </button>
                <button
                  type="button"
                  onClick={() => switchMode("login")}
                  style={{
                    background: "none",
                    color: theme.thinLine,
                    border: "none",
                    fontWeight: 700,
                    cursor: "pointer",
                    textDecoration: "underline",
                    marginTop: 2
                  }}
                >
                  Back to Login
                </button>
              </>
            )}
          </>
        )}

        {/* Account Deletion Confirmation */}
        {deleteConfirm && (
          <div style={{
            background: "#1a1212ea",
            position: "absolute",
            top: 0, left: 0, right: 0, bottom: 0,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 5
          }}>
            <div style={{
              background: "#242424",
              color: "#ffd7d7",
              padding: 34,
              borderRadius: 14,
              boxShadow: "0 6px 44px #000c",
              minWidth: 300
            }}>
              <h3 style={{ color: "#e84444", margin: "0 0 16px 0" }}>
                Delete Account
              </h3>
              <p>Are you sure? Enter your username and password to confirm:</p>
              <input
                placeholder="Username"
                value={name}
                onChange={e => setName(e.target.value)}
                style={{ width: "100%", margin: "7px 0", padding: 9, borderRadius: 5 }}
              />
              <input
                placeholder="Password"
                type="password"
                value={password}
                onChange={e => setPassword(e.target.value)}
                style={{ width: "100%", margin: "7px 0", padding: 9, borderRadius: 5 }}
              />
              <div style={{ display: "flex", gap: 18, marginTop: 15 }}>
                <button
                  type="button"
                  onClick={handleDelete}
                  style={{
                    background: "#e84444",
                    color: "#fff",
                    fontWeight: 700,
                    border: "none",
                    borderRadius: 6,
                    padding: "9px 22px",
                    cursor: "pointer"
                  }}
                >Delete</button>
                <button
                  type="button"
                  onClick={() => setDeleteConfirm(false)}
                  style={{
                    background: "#333",
                    color: "#fff",
                    fontWeight: 700,
                    border: "none",
                    borderRadius: 6,
                    padding: "9px 22px",
                    cursor: "pointer"
                  }}
                >Cancel</button>
              </div>
            </div>
          </div>
        )}

      </form>
    </div>
  );
}
