// src/components/WaterTotalWidget.jsx
import React from "react";
import { ROLE_THEMES } from "./roleThemes";
import { useAppData } from "./AppDataContext";

export default function WaterTotalWidget({ role = "all" }) {
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;
  const { water } = useAppData() || {};

  return (
    <div style={{
      background: theme.widgetBg,
      border: `3.5px solid ${theme.thinLine}`,
      borderRadius: 14,
      color: "#fff",
      padding: 20,
      minWidth: 220,
      maxWidth: 320,
      margin: "0 auto 18px auto",
      boxShadow: "0 2px 10px #0006"
    }}>
      <div style={{
        fontWeight: 900,
        fontSize: 20,
        color: theme.thinLine,
        letterSpacing: ".10em",
        marginBottom: 7,
        textAlign: "center"
      }}>
        Today's Water Intake
      </div>
      <div style={{
        fontSize: 24,
        fontWeight: 900,
        color: theme.accent,
        textAlign: "center",
        margin: "16px 0 0 0"
      }}>
        {water ?? 0} <span style={{ fontWeight: 700, color: "#ccc", fontSize: 18 }}>oz</span>
      </div>
    </div>
  );
}
