// src/components/MissionBoard.jsx

import React, { useEffect, useState } from "react";
import { ROLE_THEMES } from "./roleThemes";

// Helper to load/save missions for a given username (per account)
function getStorageKey(username) {
  return `shiftstrong_missions_${username?.toLowerCase()}`;
}
function loadMissions(username) {
  try {
    const key = getStorageKey(username);
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : [];
  } catch {
    return [];
  }
}
function saveMissions(username, missions) {
  if (!username) return;
  const key = getStorageKey(username);
  localStorage.setItem(key, JSON.stringify(missions));
}

export default function MissionBoard({ role = "all", user }) {
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;
  const username = user?.name || user?.username || "";
  const [missions, setMissions] = useState(() => loadMissions(username));
  const [input, setInput] = useState("");
  const [message, setMessage] = useState("");

  // Reload when user changes (or on mount)
  useEffect(() => {
    setMissions(loadMissions(username));
    setInput("");
  }, [username]);

  // Save missions whenever they change
  useEffect(() => {
    if (username) saveMissions(username, missions);
  }, [missions, username]);

  function handleAdd(e) {
    e.preventDefault();
    const task = input.trim();
    if (!task) return;
    if (missions.length >= 10) {
      setMessage("Max 10 missions at once.");
      setTimeout(() => setMessage(""), 1200);
      return;
    }
    setMissions([...missions, { text: task, done: false }]);
    setInput("");
    setMessage("");
  }
  function handleToggleDone(idx) {
    setMissions(missions.map((m, i) => i === idx ? { ...m, done: !m.done } : m));
  }
  function handleRemove(idx) {
    setMissions(missions.filter((_, i) => i !== idx));
  }
  function handleClear() {
    setMissions([]);
  }

  return (
    <div style={{
      color: "#fff",
      background: "none",
      border: "none",
      minHeight: 180,
      fontFamily: "'Oswald','Roboto Mono',sans-serif",
      display: "flex",
      flexDirection: "column",
      height: "100%"
    }}>
      <div style={{
        color: theme.thinLine,
        fontWeight: 900,
        fontSize: 22,
        marginBottom: 7,
        textAlign: "center",
        letterSpacing: ".08em"
      }}>
        Mission Board
      </div>
      <form
        onSubmit={handleAdd}
        style={{
          display: "flex",
          gap: 8,
          marginBottom: 8,
          justifyContent: "center",
          flexWrap: "wrap"
        }}
      >
        <input
          type="text"
          value={input}
          onChange={e => setInput(e.target.value)}
          placeholder="New mission (max 10)..."
          maxLength={80}
          style={{
            flex: 1,
            minWidth: 120,
            borderRadius: 7,
            border: `2px solid ${theme.thinLine}`,
            background: "#181d21",
            color: "#fff",
            fontWeight: 700,
            fontSize: 16,
            padding: "6px 10px"
          }}
        />
        <button
          type="submit"
          style={{
            background: theme.thinLine,
            color: "#181d21",
            border: "none",
            borderRadius: 8,
            fontWeight: 900,
            fontSize: 16,
            padding: "6px 18px",
            cursor: "pointer"
          }}
        >
          Add
        </button>
        {missions.length > 0 && (
          <button
            type="button"
            onClick={handleClear}
            style={{
              background: "#e84444",
              color: "#fff",
              border: "none",
              borderRadius: 8,
              fontWeight: 900,
              fontSize: 16,
              padding: "6px 13px",
              cursor: "pointer"
            }}
            title="Clear all missions"
          >
            Clear
          </button>
        )}
      </form>
      {message && (
        <div style={{
          color: "#e84444",
          fontWeight: 800,
          fontSize: 15,
          textAlign: "center",
          marginBottom: 7
        }}>
          {message}
        </div>
      )}
      <ul style={{
        listStyle: "none",
        margin: 0,
        padding: 0,
        minHeight: 80,
        maxHeight: 180,
        overflowY: "auto"
      }}>
        {missions.length === 0 && (
          <li style={{ color: "#bbb", textAlign: "center", fontWeight: 600 }}>
            No missions yet. Stay tactical—set your top priorities for today!
          </li>
        )}
        {missions.map((m, idx) => (
          <li key={idx}
            style={{
              display: "flex",
              alignItems: "center",
              gap: 8,
              marginBottom: 2,
              borderBottom: "1px solid #212a",
              padding: "3px 0"
            }}
          >
            <input
              type="checkbox"
              checked={!!m.done}
              onChange={() => handleToggleDone(idx)}
              style={{ accentColor: theme.thinLine, width: 18, height: 18 }}
            />
            <span style={{
              textDecoration: m.done ? "line-through" : "none",
              color: m.done ? "#ccc" : "#fff",
              flex: 1,
              fontWeight: 700,
              fontSize: 15
            }}>
              {m.text}
            </span>
            <button
              type="button"
              onClick={() => handleRemove(idx)}
              style={{
                background: "none",
                color: "#e84444",
                border: "none",
                borderRadius: 5,
                fontWeight: 900,
                fontSize: 15,
                padding: "2px 7px",
                cursor: "pointer"
              }}
              title="Remove"
            >
              ✕
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

