// src/components/AIAssistant.jsx

import React, { useState } from "react";
import { ROLE_THEMES } from "./roleThemes";

// SET THIS TO YOUR DEPLOYED BACKEND URL:
const API_URL = "https://your-cloud-backend.onrender.com/api/chat"; // ← change to your backend!

export default function AIAssistant({ role = "all", user }) {
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;

  const [messages, setMessages] = useState([
    { role: "assistant", content: "Hi! I'm your ShiftStrong AI assistant. How can I help you today?" }
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  async function sendMessage(e) {
    e.preventDefault();
    if (!input.trim()) return;
    setMessages(msgs => [...msgs, { role: "user", content: input }]);
    setInput("");
    setLoading(true);
    setError("");
    try {
      const response = await fetch(API_URL, {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          messages: [
            ...messages,
            { role: "user", content: input }
          ],
          role: role || "all"
        })
      });
      if (!response.ok) {
        throw new Error("Server error or unavailable.");
      }
      const data = await response.json();
      const reply = data.reply || "Sorry, I couldn't get a response.";
      setMessages(msgs => [...msgs, { role: "assistant", content: reply }]);
    } catch (err) {
      setMessages(msgs => [...msgs, { role: "assistant", content: "AI Assistant unavailable. Check your network or try later." }]);
      setError("Network or server error.");
    }
    setLoading(false);
  }

  return (
    <div style={{
      background: theme.widgetBg,
      border: `3.5px solid ${theme.thinLine}`,
      borderRadius: 15,
      color: "#fff",
      boxShadow: "0 2px 13px #0006",
      padding: 20,
      maxWidth: 540,
      minHeight: 400,
      margin: "32px auto",
      display: "flex",
      flexDirection: "column"
    }}>
      <div style={{
        color: theme.thinLine,
        fontWeight: 900,
        fontSize: 24,
        letterSpacing: ".09em",
        marginBottom: 8
      }}>
        ShiftStrong AI Assistant
      </div>
      <div style={{
        color: theme.accent,
        fontSize: 18,
        marginBottom: 10
      }}>
        {`Hello, ${user?.name || "Operator"}! Ask me anything about fitness, nutrition, tactical performance, and more.`}
      </div>
      <div style={{
        flex: 1,
        overflowY: "auto",
        marginBottom: 14,
        background: "#181d21",
        borderRadius: 10,
        padding: 14,
        minHeight: 160
      }}>
        {messages.map((msg, idx) =>
          <div key={idx} style={{
            color: msg.role === "assistant" ? theme.accent : "#b7ce63",
            margin: "8px 0",
            fontWeight: msg.role === "assistant" ? 800 : 700,
            whiteSpace: "pre-line"
          }}>
            <b>{msg.role === "assistant" ? "AI:" : "You:"}</b> {msg.content}
          </div>
        )}
        {loading && <div style={{ color: theme.thinLine }}>AI is typing...</div>}
      </div>
      {error && (
        <div style={{
          background: "#c24141",
          color: "#fff",
          borderRadius: 6,
          padding: 8,
          marginBottom: 6,
          textAlign: "center",
          fontWeight: 800
        }}>{error}</div>
      )}
      <form style={{ display: "flex", gap: 10 }} onSubmit={sendMessage}>
        <input
          style={{
            flex: 1,
            padding: "10px",
            borderRadius: 8,
            border: `2px solid ${theme.thinLine}`,
            background: "#181d21",
            color: "#fff",
            fontWeight: 700,
            fontSize: 17
          }}
          placeholder="Ask a question..."
          value={input}
          onChange={e => setInput(e.target.value)}
          disabled={loading}
          autoFocus
        />
        <button
          type="submit"
          style={{
            padding: "0 24px",
            borderRadius: 8,
            fontSize: 17,
            fontWeight: 900,
            background: theme.thinLine,
            color: "#101316",
            border: "none",
            cursor: loading ? "wait" : "pointer"
          }}
          disabled={loading}
        >Send</button>
      </form>
    </div>
  );
}
