// src/components/WaterTracker.jsx

import React, { useState, useEffect } from "react";
import { ROLE_THEMES } from "./roleThemes";
import { useAppData } from "./AppDataContext";
import WaterGoalWidget from "./WaterGoalWidget";
import WaterTotalWidget from "./WaterTotalWidget";
import WaterProgressBar from "./WaterProgressBar";

const VOLUME_UNITS = [
  { label: "oz", factor: 1 },
  { label: "ml", factor: 29.5735 }
];
const DEFAULT_UNIT = "oz";
function loadUnit() {
  try { return localStorage.getItem("water_unit") || DEFAULT_UNIT; } catch { return DEFAULT_UNIT; }
}
function saveUnit(unit) { localStorage.setItem("water_unit", unit); }

export default function WaterTracker({ role = "all" }) {
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;
  const { water, setWater } = useAppData() || {};
  const [message, setMessage] = useState("");
  const [unit, setUnit] = useState(() => loadUnit());
  const [addAmount, setAddAmount] = useState(8);

  useEffect(() => { saveUnit(unit); }, [unit]);

  function handleUnitChange(e) { setUnit(e.target.value); }
  function handleChange(e) { setAddAmount(e.target.value.replace(/[^0-9]/g, "")); }
  function handleAdd(e) {
    e.preventDefault();
    const amt = Math.abs(Number(addAmount) || 0);
    if (amt === 0) return;
    const addOz = unit === "ml" ? amt / VOLUME_UNITS[1].factor : amt;
    setWater((w) => (w ?? 0) + Math.round(addOz));
    setMessage(`Added ${amt} ${unit}.`);
    setTimeout(() => setMessage(""), 1200);
  }
  function handleSubtract(e) {
    e.preventDefault();
    const amt = Math.abs(Number(addAmount) || 0);
    if (amt === 0) return;
    const subOz = unit === "ml" ? amt / VOLUME_UNITS[1].factor : amt;
    setWater((w) => Math.max(0, (w ?? 0) - Math.round(subOz)));
    setMessage(`Subtracted ${amt} ${unit}.`);
    setTimeout(() => setMessage(""), 1200);
  }
  function handleReset() {
    setWater(0);
    setMessage("Water log reset.");
    setTimeout(() => setMessage(""), 1200);
  }

  return (
    <div style={{
      minWidth: 0, width: "100%", flex: 1, padding: 0, color: "#fff", fontFamily: "'Oswald','Roboto Mono',sans-serif", background: "none", border: "none", boxShadow: "none"
    }}>
      <div style={{
        color: theme.thinLine, fontWeight: 900, fontSize: 24,
        letterSpacing: ".09em", marginBottom: 9, textAlign: "center"
      }}>
      </div>
      <WaterGoalWidget role={role} />
      <WaterTotalWidget role={role} />
      <WaterProgressBar role={role} />
      <form onSubmit={handleAdd} style={{ marginTop: 10, width: "100%" }}>
        <div style={{
          display: "flex", gap: 13, alignItems: "center",
          justifyContent: "center", marginBottom: 10, flexWrap: "wrap"
        }}>
          <input
            type="number"
            min={1}
            value={addAmount}
            onChange={handleChange}
            style={{
              width: 70, borderRadius: 6, border: `2px solid ${theme.thinLine}`,
              background: "#181d21", color: "#fff", fontWeight: 700,
              fontSize: 17, padding: "4px 7px", textAlign: "right"
            }}
            required
          />
          <select
            value={unit}
            onChange={handleUnitChange}
            style={{
              borderRadius: 7, border: `2px solid ${theme.thinLine}`,
              background: "#181d21", color: "#fff", fontWeight: 700,
              fontSize: 16, padding: "6px 10px"
            }}
          >
            {VOLUME_UNITS.map(u =>
              <option key={u.label} value={u.label}>{u.label}</option>
            )}
          </select>
          <button type="submit"
            style={{
              border: "none", borderRadius: 8, background: theme.thinLine,
              color: "#181d21", fontWeight: 900, fontSize: 16,
              padding: "6px 22px", cursor: "pointer"
            }}>
            Add
          </button>
          <button type="button"
            onClick={handleSubtract}
            style={{
              border: "none", borderRadius: 8, background: "#e84444",
              color: "#fff", fontWeight: 900, fontSize: 16,
              padding: "6px 22px", cursor: "pointer"
            }}>
            Subtract
          </button>
        </div>
        <div style={{
          display: "flex", gap: 10, justifyContent: "center"
        }}>
          <button type="button" onClick={handleReset}
            style={{
              border: "none", borderRadius: 8, background: "#666",
              color: "#fff", fontWeight: 800, fontSize: 15,
              padding: "6px 16px", cursor: "pointer"
            }}>
            Reset
          </button>
        </div>
        {message && <div style={{
          color: theme.thinLine, fontWeight: 800, marginTop: 10, textAlign: "center"
        }}>{message}</div>}
      </form>
    </div>
  );
}


