// src/components/HomeOverview.jsx

import React, { useState } from "react";
import MacroTracker from "./MacroTracker";
import WaterTracker from "./WaterTracker";
import WeightliftingLog from "./WeightliftingLog";
import ProgressLog from "./ProgressLog";
import StreaksAchievements from "./StreaksAchievements";
import GoalSetting from "./GoalSetting";
import MissionBoard from "./MissionBoard";
import AIAssistant from "./AIAssistant";
import { ROLE_THEMES } from "./roleThemes";
import { FaChevronLeft, FaChevronRight } from "react-icons/fa";

function WidgetErrorBoundary({ children, fallback }) {
  const [hasError, setHasError] = React.useState(false);
  return hasError
    ? (fallback || <div style={{ color: "#e44", fontWeight: 700 }}>Widget failed to load.</div>)
    : (
      <React.Suspense fallback={<div>Loading...</div>}>
        {React.cloneElement(children, {
          onError: () => setHasError(true)
        })}
      </React.Suspense>
    );
}

// Widgets for carousel
const getCarouselWidgets = (role) => [
  {
    key: "macros",
    name: "Macro Tracker",
    content: <MacroTracker role={role} />,
  },
  {
    key: "water",
    name: "Water Tracker",
    content: <WaterTracker role={role} />,
  },
  {
    key: "weight",
    name: "Weightlifting Log",
    content: <WeightliftingLog role={role} />,
  },
  {
    key: "progress",
    name: "Progress Log",
    content: <ProgressLog role={role} />,
  },
  {
    key: "streaks",
    name: "Streaks & Achievements",
    content: <StreaksAchievements role={role} />,
  },
  {
    key: "goals",
    name: "Goal Setting",
    content: <GoalSetting role={role} />,
  }
];

export default function HomeOverview({ user }) {
  const role = user?.role || "all";
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;
  const widgets = getCarouselWidgets(role);
  const [activeIdx, setActiveIdx] = useState(0);

  function goNext() {
    setActiveIdx(i => (i + 1) % widgets.length);
  }
  function goPrev() {
    setActiveIdx(i => (i - 1 + widgets.length) % widgets.length);
  }

  const cardStyle = {
    minWidth: 0,
    width: 420,
    maxWidth: "94vw",
    minHeight: 400,
    maxHeight: "78vh",
    margin: "0 auto",
    display: "flex",
    flexDirection: "column",
    background: theme.widgetBg,
    border: `3.5px solid ${theme.thinLine}`,
    borderRadius: 18,
    boxShadow: "0 2px 15px #0007",
    padding: "32px 24px 24px 24px",
    alignItems: "stretch",
    justifyContent: "center",
    position: "relative",
    transition: "background 0.2s"
  };

  // Top grid for MissionBoard and AI Assistant
  const topRowStyle = {
    display: "grid",
    gridTemplateColumns: "1fr 1fr",
    gap: 30,
    width: "100%",
    margin: "0 auto 30px auto",
    maxWidth: 1100,
    alignItems: "stretch"
  };

  return (
    <div
      style={{
        minHeight: "calc(100vh - 64px)",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "flex-start",
        background: "inherit",
        width: "100%",
        padding: "20px 10px 40px 10px",
        boxSizing: "border-box"
      }}
    >
      {/* Top Row: MissionBoard + AI Assistant */}
      <div style={topRowStyle}>
        <div style={cardStyle}>
          <WidgetErrorBoundary>
            <MissionBoard role={role} />
          </WidgetErrorBoundary>
        </div>
        <div style={cardStyle}>
          <WidgetErrorBoundary>
            <AIAssistant role={role} user={user} />
          </WidgetErrorBoundary>
        </div>
      </div>

      {/* Carousel below */}
      <div style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        gap: 0,
        width: "100%",
        maxWidth: 700,
        minHeight: 480
      }}>
        {/* Left Arrow */}
        <button
          onClick={goPrev}
          aria-label="Previous Widget"
          style={{
            border: "none",
            background: "none",
            color: theme.thinLine,
            fontSize: 32,
            cursor: "pointer",
            padding: 0,
            marginRight: 16,
            height: 64,
            width: 48,
            display: "flex",
            alignItems: "center",
            justifyContent: "center"
          }}
        >
          <FaChevronLeft />
        </button>

        {/* The Widget Card */}
        <div style={cardStyle}>
          <div style={{
            textAlign: "center",
            fontWeight: 900,
            fontSize: 23,
            color: theme.thinLine,
            marginBottom: 18,
            letterSpacing: ".10em",
            textShadow: "0 1px 6px #0008"
          }}>
            {widgets[activeIdx].name}
          </div>
          <WidgetErrorBoundary>
            {widgets[activeIdx].content}
          </WidgetErrorBoundary>
          <div style={{
            position: "absolute",
            bottom: 12,
            left: 0,
            width: "100%",
            textAlign: "center",
            color: theme.accent,
            fontWeight: 700,
            fontSize: 15,
            letterSpacing: ".06em"
          }}>
            {activeIdx + 1} / {widgets.length}
          </div>
        </div>

        {/* Right Arrow */}
        <button
          onClick={goNext}
          aria-label="Next Widget"
          style={{
            border: "none",
            background: "none",
            color: theme.thinLine,
            fontSize: 32,
            cursor: "pointer",
            padding: 0,
            marginLeft: 16,
            height: 64,
            width: 48,
            display: "flex",
            alignItems: "center",
            justifyContent: "center"
          }}
        >
          <FaChevronRight />
        </button>
      </div>
    </div>
  );
}


