// src/App.jsx

import React, { useState, useEffect } from "react";
import SplashScreen from "./components/SplashScreen";
import Login from "./components/Login";
import TacticalDashboard from "./components/TacticalDashboard";
import { AppDataProvider } from "./components/AppDataContext";

// For demo: Splash screen for 1.2s, then login/dashboard
const SPLASH_TIME = 1200;

export default function App() {
  const [screen, setScreen] = useState("splash"); // "splash", "login", "dashboard"
  const [user, setUser] = useState(null);

  // Show splash on first load
  useEffect(() => {
    setScreen("splash");
    const timer = setTimeout(() => {
      setScreen("login");
    }, SPLASH_TIME);
    return () => clearTimeout(timer);
  }, []);

  // Handle login and logout
  function handleLogin(userData) {
    setUser(userData);
    setScreen("dashboard");
  }
  function handleLogout() {
    setUser(null);
    setScreen("login");
    // Optional: clear app data or localStorage here
  }

  // Route screen
  let content = null;
  if (screen === "splash") {
    content = <SplashScreen />;
  } else if (!user) {
    content = <Login onLogin={handleLogin} />;
  } else {
    content = (
      <TacticalDashboard user={user} onLogout={handleLogout} />
    );
  }

  return (
    <AppDataProvider user={user}>
      {content}
    </AppDataProvider>
  );
}

