// src/components/SettingsTab.jsx

import React, { useEffect, useState } from "react";
import { ROLE_THEMES } from "./roleThemes";

const DEFAULT_SETTINGS = {
  units: "standard",
  sound: true,
  notifications: true,
  reminders: false,
  darkMode: true,
  confirmReset: true,
};

function loadSettings() {
  try {
    const stored = localStorage.getItem("shiftstrong_settings");
    return stored ? JSON.parse(stored) : { ...DEFAULT_SETTINGS };
  } catch {
    return { ...DEFAULT_SETTINGS };
  }
}
function saveSettings(settings) {
  localStorage.setItem("shiftstrong_settings", JSON.stringify(settings));
}

export default function SettingsTab({ role = "all", userSettings }) {
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;
  const [settings, setSettings] = useState(() =>
    userSettings ? { ...DEFAULT_SETTINGS, ...userSettings } : loadSettings()
  );
  const [message, setMessage] = useState("");

  useEffect(() => {
    saveSettings(settings);
  }, [settings]);

  function handleChange(key, value) {
    setSettings(prev => ({ ...prev, [key]: value }));
  }

  function handleSave(e) {
    e.preventDefault();
    setMessage("Settings saved!");
    setTimeout(() => setMessage(""), 1800);
  }

  function handleResetAll() {
    if (window.confirm("Reset all app data and settings? This cannot be undone.")) {
      localStorage.clear();
      setSettings({ ...DEFAULT_SETTINGS });
      setMessage("All data and settings reset.");
      setTimeout(() => setMessage(""), 2000);
      window.location.reload();
    }
  }

  return (
    <div style={{
      background: theme.widgetBg,
      border: `3.5px solid ${theme.thinLine}`,
      borderRadius: 16,
      color: "#fff",
      boxShadow: "0 2px 13px #0006",
      maxWidth: 480,
      margin: "38px auto",
      padding: "34px 30px 26px 30px",
      fontFamily: "'Oswald','Roboto Mono',sans-serif"
    }}>
      <div style={{
        color: theme.thinLine,
        fontWeight: 900,
        fontSize: 26,
        letterSpacing: ".09em",
        marginBottom: 16,
        textAlign: "center"
      }}>
        Settings
      </div>
      <form onSubmit={handleSave} style={{ display: "flex", flexDirection: "column", gap: 18 }}>
        <label style={{ fontWeight: 800, color: theme.accent, fontSize: 18 }}>
          Units:
          <select
            style={{
              marginLeft: 13,
              borderRadius: 7,
              border: `2px solid ${theme.thinLine}`,
              background: "#181d21",
              color: "#fff",
              fontWeight: 700,
              fontSize: 17,
              padding: "7px 13px"
            }}
            value={settings.units}
            onChange={e => handleChange("units", e.target.value)}
          >
            <option value="standard">Standard (lbs, oz)</option>
            <option value="metric">Metric (kg, ml)</option>
          </select>
        </label>
        <label style={{ fontWeight: 800, color: theme.accent, fontSize: 18 }}>
          <input
            type="checkbox"
            checked={!!settings.sound}
            onChange={e => handleChange("sound", e.target.checked)}
            style={{
              marginRight: 11,
              accentColor: theme.thinLine
            }}
          />
          Sound Effects
        </label>
        <label style={{ fontWeight: 800, color: theme.accent, fontSize: 18 }}>
          <input
            type="checkbox"
            checked={!!settings.notifications}
            onChange={e => handleChange("notifications", e.target.checked)}
            style={{
              marginRight: 11,
              accentColor: theme.thinLine
            }}
          />
          Enable Notifications
        </label>
        <label style={{ fontWeight: 800, color: theme.accent, fontSize: 18 }}>
          <input
            type="checkbox"
            checked={!!settings.reminders}
            onChange={e => handleChange("reminders", e.target.checked)}
            style={{
              marginRight: 11,
              accentColor: theme.thinLine
            }}
          />
          Daily Workout Reminder
        </label>
        <label style={{ fontWeight: 800, color: theme.accent, fontSize: 18 }}>
          <input
            type="checkbox"
            checked={!!settings.darkMode}
            onChange={e => handleChange("darkMode", e.target.checked)}
            style={{
              marginRight: 11,
              accentColor: theme.thinLine
            }}
          />
          Dark Mode
        </label>
        <label style={{ fontWeight: 800, color: theme.accent, fontSize: 18 }}>
          <input
            type="checkbox"
            checked={!!settings.confirmReset}
            onChange={e => handleChange("confirmReset", e.target.checked)}
            style={{
              marginRight: 11,
              accentColor: theme.thinLine
            }}
          />
          Confirm Before Resets
        </label>
        <button
          type="submit"
          style={{
            marginTop: 15,
            padding: "12px 0",
            borderRadius: 8,
            fontSize: 18,
            fontWeight: 900,
            letterSpacing: ".09em",
            background: theme.thinLine,
            color: "#181d21",
            border: "none",
            cursor: "pointer"
          }}
        >
          Save Settings
        </button>
        <button
          type="button"
          style={{
            marginTop: 4,
            padding: "10px 0",
            borderRadius: 8,
            fontSize: 17,
            fontWeight: 800,
            background: "#e84444",
            color: "#fff",
            border: "none",
            cursor: "pointer"
          }}
          onClick={handleResetAll}
        >
          Reset All Data
        </button>
        {message && (
          <div style={{
            color: theme.thinLine,
            fontWeight: 800,
            background: "#161b21",
            borderRadius: 8,
            padding: "10px 0",
            marginTop: 6,
            textAlign: "center",
            border: `1.5px solid ${theme.thinLine}`
          }}>
            {message}
          </div>
        )}
      </form>
    </div>
  );
}

