// src/components/TacticalDashboard.jsx

import React, { useState } from "react";
import HomeOverview from "./HomeOverview";
import MacroTracker from "./MacroTracker";
import WaterTracker from "./WaterTracker";
import WeightliftingLog from "./WeightliftingLog";
import ProgressLog from "./ProgressLog";
import StreaksAchievements from "./StreaksAchievements";
import GoalSetting from "./GoalSetting";
import CalendarView from "./CalendarView";
import WorkoutDescriptions from "./WorkoutDescriptions";
import SettingsTab from "./SettingsTab";
import BannerBar from "./BannerBar";
import { ROLE_THEMES } from "./roleThemes";
import {
  FaHome, FaTint, FaDumbbell, FaChartLine,
  FaStar, FaBullseye, FaCalendarAlt, FaInfoCircle, FaCog
} from "react-icons/fa";

export default function TacticalDashboard({ user, onLogout }) {
  const [tab, setTab] = useState("home");
  const role = user?.role || "all";
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;
  const [expanded, setExpanded] = useState(false);

  // Tab definitions
  const TABS = [
    { key: "home", label: "Home", icon: <FaHome size={22} /> },
    { key: "macros", label: "Macros", icon: <FaTint size={22} /> },
    { key: "water", label: "Water", icon: <FaTint size={22} /> },
    { key: "weight", label: "Lifting", icon: <FaDumbbell size={22} /> },
    { key: "progress", label: "Progress", icon: <FaChartLine size={22} /> },
    { key: "streaks", label: "Streaks", icon: <FaStar size={22} /> },
    { key: "goals", label: "Goals", icon: <FaBullseye size={22} /> },
    { key: "calendar", label: "Calendar", icon: <FaCalendarAlt size={22} /> },
    { key: "workouts", label: "Workouts", icon: <FaInfoCircle size={22} /> },
    { key: "settings", label: "Settings", icon: <FaCog size={22} /> }
  ];

  function renderTab(tabKey) {
    switch (tabKey) {
      case "home":      return <HomeOverview user={user} />;
      case "macros":    return <MacroTracker role={role} />;
      case "water":     return <WaterTracker role={role} />;
      case "weight":    return <WeightliftingLog role={role} />;
      case "progress":  return <ProgressLog role={role} />;
      case "streaks":   return <StreaksAchievements role={role} />;
      case "goals":     return <GoalSetting role={role} />;
      case "calendar":  return <CalendarView role={role} />;
      case "workouts":  return <WorkoutDescriptions role={role} />;
      case "settings":  return <SettingsTab user={user} onLogout={onLogout} />;
      default:          return <HomeOverview user={user} />;
    }
  }

  // Sidebar styles
  const sidebarBg = `linear-gradient(180deg, #181d24 65%, #212a36 100%)`;
  const sidebarBorder = `4px solid ${theme.thinLine}`;
  const sidebarShadow = "0 4px 36px #0e1528b3";
  const cardLift = "0 2px 16px #0a1126bb";
  const mainBg = `
    repeating-linear-gradient(135deg, #242933 0 8px, #21262e 8px 16px),
    linear-gradient(125deg, #1a1d22 80%, ${theme.widgetBg} 100%)
  `;

  return (
    <div style={{
      display: "flex",
      width: "100vw",
      minHeight: "100vh",
      background: mainBg,
      backgroundBlendMode: "overlay",
      position: "relative",
      overflow: "hidden"
    }}>
      {/* Sidebar */}
      <div
        style={{
          background: sidebarBg,
          minWidth: expanded ? 196 : 62,
          width: expanded ? 196 : 62,
          transition: "width 0.21s cubic-bezier(.33,1.02,.6,.99)",
          display: "flex",
          flexDirection: "column",
          alignItems: expanded ? "flex-start" : "center",
          paddingTop: 28,
          paddingBottom: 28,
          borderRight: sidebarBorder,
          boxShadow: sidebarShadow,
          zIndex: 12,
          position: "relative",
          userSelect: "none"
        }}
        onMouseEnter={() => setExpanded(true)}
        onMouseLeave={() => setExpanded(false)}
      >
        {/* Badge at top */}
        <div style={{
          width: 60, height: 60,
          alignSelf: "center",
          marginBottom: 16,
          display: "flex", alignItems: "center", justifyContent: "center",
          background: "#161d26",
          borderRadius: 16,
          boxShadow: "0 1px 14px #121e44"
        }}>
          <img
            src={require(`../assets/${role}_badge.png`)}
            alt={`${role} badge`}
            style={{
              width: 52, height: 52,
              borderRadius: 16,
              objectFit: "contain",
              background: theme.widgetBg,
              boxShadow: "0 2px 9px #0008"
            }}
          />
        </div>
        <div style={{
          color: theme.thinLine,
          fontWeight: 900,
          fontSize: 21,
          letterSpacing: ".12em",
          textAlign: "center",
          marginBottom: 17,
          alignSelf: expanded ? "flex-start" : "center",
          textShadow: "0 3px 12px #001b"
        }}>
          {expanded ? "SHIFTSTRONG" : "SS"}
        </div>
        {/* Tab Buttons */}
        <div style={{ flex: 1, width: "100%" }}>
          {TABS.map(({ key, label, icon }) => (
            <button
              key={key}
              onClick={() => setTab(key)}
              style={{
                display: "flex",
                alignItems: "center",
                gap: expanded ? 18 : 0,
                width: "100%",
                padding: expanded ? "15px 18px" : "15px 0",
                background: tab === key
                  ? `linear-gradient(90deg, ${theme.thinLine} 0 78%, #fff2 100%)`
                  : "transparent",
                color: tab === key ? "#181d21" : "#c2d4f7",
                border: "none",
                fontWeight: 900,
                fontSize: 18,
                borderRadius: expanded ? "13px" : "50%",
                margin: expanded ? "6px 0" : "6px auto",
                cursor: "pointer",
                justifyContent: expanded ? "flex-start" : "center",
                boxShadow: tab === key ? "0 0 12px #2f86e9a8" : "none",
                transition: "all .14s"
              }}
              title={label}
            >
              <span style={{
                filter: tab === key ? `drop-shadow(0 2px 7px ${theme.thinLine}88)` : "none",
                textShadow: tab === key ? `0 1px 3px #1a2` : "none"
              }}>{icon}</span>
              {expanded && <span style={{ fontWeight: 900, fontSize: 16 }}>{label}</span>}
            </button>
          ))}
        </div>
        {/* Subtle steel bar at sidebar bottom */}
        <div style={{
          width: "85%",
          height: 6,
          background: "linear-gradient(90deg, #444a57, #21283c 60%, #444a57)",
          borderRadius: 5,
          alignSelf: "center",
          margin: "32px 0 0 0",
          opacity: 0.6
        }} />
      </div>

      {/* Main dashboard area */}
      <div style={{
        flex: 1,
        minHeight: "100vh",
        background: `linear-gradient(115deg, #191c22 80%, ${theme.widgetBg} 100%)`,
        display: "flex",
        flexDirection: "column",
        position: "relative",
        overflow: "hidden"
      }}>
        {/* Banner Bar */}
        <div style={{
          width: "100%",
          minHeight: 46,
          background: theme.thinLine,
          boxShadow: "0 2px 14px #0006"
        }}>
          <BannerBar role={role} />
        </div>
        {/* Title Row */}
        <div style={{
          display: "flex",
          alignItems: "center",
          gap: 18,
          padding: "16px 42px 10px 38px",
          borderBottom: `2.5px solid ${theme.thinLine}`,
          background: "linear-gradient(90deg, #161b22 60%, #1c2331 100%)",
          boxShadow: "0 1.5px 11px #141c23"
        }}>
          <img
            src={require(`../assets/${role}_badge.png`)}
            alt={`${role} badge`}
            style={{
              width: 40, height: 40,
              borderRadius: 12,
              objectFit: "contain",
              background: "#1a1a1d",
              boxShadow: "0 1px 7px #0007"
            }}
          />
          <span style={{
            color: theme.thinLine,
            fontSize: 29,
            fontWeight: 900,
            letterSpacing: ".10em",
            textShadow: "0 2px 9px #061b"
          }}>
            SHIFT<strong style={{ color: theme.accent }}>STRONG</strong>
          </span>
          <span style={{
            fontSize: 15,
            fontWeight: 700,
            color: theme.accent,
            marginLeft: 18,
            opacity: 0.88,
            textTransform: "uppercase"
          }}>
            {theme.name}
          </span>
        </div>
        {/* Dashboard Content Area */}
        <div style={{
          flex: 1,
          minHeight: 0,
          width: "100%",
          padding: "32px 0 36px 0",
          boxSizing: "border-box",
          background: "none",
          overflowY: "auto",
          display: "flex",
          flexDirection: "column"
        }}>
          <div style={{
            maxWidth: 1400,
            margin: "0 auto",
            width: "97vw",
            minHeight: 500,
            background: "none",
            boxShadow: cardLift,
            borderRadius: 18,
            display: "flex",
            flexDirection: "column",
            justifyContent: "flex-start",
            padding: "0 10px"
          }}>
            {renderTab(tab)}
          </div>
        </div>
      </div>
    </div>
  );
}
