// src/components/ProgressLog.jsx

import React, { useMemo } from "react";
import { useAppData } from "./AppDataContext";
import { ROLE_THEMES } from "./roleThemes";
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from "recharts";

export default function ProgressLog({ role = "all" }) {
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;
  const { weightLifts = [], macros = {}, water = 0, prHistory = [] } = useAppData() || {};

  // Aggregate PRs, total weight, macro and water data per day
  const data = useMemo(() => {
    // We assume each entry in prHistory is { date, value }
    // and weightLifts is an array of { date, weight, reps, sets }
    // and macros is stored by date
    const map = {};

    (prHistory || []).forEach(pr => {
      if (!pr?.date) return;
      if (!map[pr.date]) map[pr.date] = {};
      map[pr.date].pr = Math.max(map[pr.date].pr || 0, pr.value || 0);
    });
    (weightLifts || []).forEach(lift => {
      if (!lift?.date) return;
      if (!map[lift.date]) map[lift.date] = {};
      map[lift.date].weight = (map[lift.date].weight || 0) + (lift.weight || 0) * (lift.reps || 0) * (lift.sets || 1);
    });
    Object.keys(macros || {}).forEach(date => {
      map[date] = { ...(map[date] || {}), macros: macros[date] };
    });
    // water may be by day: { "2025-07-01": ... }
    if (typeof water === "object" && water !== null) {
      Object.keys(water).forEach(date => {
        map[date] = { ...(map[date] || {}), water: water[date] };
      });
    }
    // Convert to array
    return Object.keys(map).sort().map(date => ({
      date,
      ...map[date]
    }));
  }, [weightLifts, macros, water, prHistory]);

  // Color palette by role
  const lineColor = theme.accent;
  const prColor = "#fa7036";
  const totalColor = "#69e67e";
  const macroColor = "#64c6ff";
  const waterColor = "#00e6dc";

  return (
    <div style={{
      minWidth: 0, width: "100%", flex: 1, padding: 0, color: "#fff",
      fontFamily: "'Oswald','Roboto Mono',sans-serif", background: "none", border: "none", boxShadow: "none",
      display: "flex", flexDirection: "column", minHeight: 0, height: "100%"
    }}>
      <div style={{
        color: theme.thinLine, fontWeight: 900, fontSize: 22,
        letterSpacing: ".09em", marginBottom: 6, textAlign: "center"
      }}>
        Progress Log
      </div>
      <div style={{
        width: "100%",
        height: 280,
        maxWidth: 560,
        margin: "0 auto",
        background: "#191e26",
        borderRadius: 12,
        padding: 8
      }}>
        <ResponsiveContainer width="100%" height="100%">
          <LineChart data={data}>
            <CartesianGrid stroke="#232c39" strokeDasharray="4 6" />
            <XAxis dataKey="date" tick={{ fill: "#ddd", fontWeight: 600, fontSize: 13 }} />
            <YAxis tick={{ fill: "#ddd", fontWeight: 600, fontSize: 13 }} />
            <Tooltip
              contentStyle={{ background: "#181d22", color: "#fff", borderRadius: 7, border: `2px solid ${theme.thinLine}` }}
            />
            <Legend />
            <Line type="monotone" dataKey="pr" name="Best PR" stroke={prColor} strokeWidth={3} dot={{ r: 4 }} />
            <Line type="monotone" dataKey="weight" name="Total Weight" stroke={totalColor} strokeWidth={2.2} dot={false} />
            <Line type="monotone" dataKey="macros.protein" name="Protein" stroke={macroColor} strokeWidth={2.5} dot={false} />
            <Line type="monotone" dataKey="water" name="Water" stroke={waterColor} strokeWidth={2.1} dot={false} />
          </LineChart>
        </ResponsiveContainer>
      </div>
      <div style={{ flex: 1 }} /> {/* Pushes tip to the bottom */}
      <div style={{
        marginTop: "auto",
        color: "#b6c4dc",
        fontWeight: 600,
        fontSize: 15,
        textAlign: "center",
        background: "none",
        padding: "16px 0 0 0"
      }}>
        Tip: These graphs show your real logged history. Log your PRs and lifts for full tactical insights!
      </div>
    </div>
  );
}

