// src/components/CalendarView.jsx

import React, { useMemo, useState } from "react";
import { ROLE_THEMES } from "./roleThemes";
import { useAppData } from "./AppDataContext";

// Calendar utility functions
const DAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
function pad(n) { return n < 10 ? `0${n}` : `${n}`; }
function getMonthStr(date) {
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}`;
}

export default function CalendarView({ role = "all" }) {
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;
  const { workoutHistory = [] } = useAppData() || {};
  const [viewMonth, setViewMonth] = useState(getMonthStr(new Date()));

  // Map: { "YYYY-MM-DD": [type, type, ...] }
  const workoutsByDate = useMemo(() => {
    const map = {};
    workoutHistory.forEach(entry => {
      if (!entry?.date) return;
      if (!map[entry.date]) map[entry.date] = [];
      map[entry.date].push(entry.type || entry.workoutType || "Workout");
    });
    return map;
  }, [workoutHistory]);

  // Calendar matrix (weeks)
  const [year, month] = viewMonth.split("-").map(Number);
  const jsMonth = month - 1;
  const firstDay = new Date(year, jsMonth, 1);
  const lastDay = new Date(year, jsMonth + 1, 0);
  let grid = [];
  let week = [];
  let iter = new Date(year, jsMonth, 1 - firstDay.getDay());
  do {
    for (let d = 0; d < 7; d++) {
      week.push(new Date(iter));
      iter.setDate(iter.getDate() + 1);
    }
    grid.push(week);
    week = [];
  } while (
    iter.getMonth() === jsMonth ||
    (iter.getMonth() === jsMonth + 1 && iter.getDate() <= 7)
  );

  function changeMonth(delta) {
    const dt = new Date(year, jsMonth + delta, 1);
    setViewMonth(getMonthStr(dt));
  }

  return (
    <div style={{
      minWidth: 0,
      width: "100%",
      flex: 1,
      padding: 0,
      color: "#fff",
      fontFamily: "'Oswald','Roboto Mono',sans-serif",
      background: "none",
      border: "none",
      boxShadow: "none"
    }}>
      <div style={{
        color: theme.thinLine,
        fontWeight: 900,
        fontSize: 22,
        letterSpacing: ".09em",
        marginBottom: 10,
        textAlign: "center"
      }}>
        Workout Calendar
      </div>
      <div style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        gap: 20,
        marginBottom: 15
      }}>
        <button
          onClick={() => changeMonth(-1)}
          style={{
            background: theme.thinLine,
            color: "#181d21",
            border: "none",
            borderRadius: 6,
            padding: "7px 16px",
            fontWeight: 900,
            cursor: "pointer",
            fontSize: 17
          }}
        >&lt;</button>
        <span style={{ fontWeight: 700, fontSize: 19 }}>
          {new Date(year, jsMonth).toLocaleString("default", { month: "long", year: "numeric" })}
        </span>
        <button
          onClick={() => changeMonth(1)}
          style={{
            background: theme.thinLine,
            color: "#181d21",
            border: "none",
            borderRadius: 6,
            padding: "7px 16px",
            fontWeight: 900,
            cursor: "pointer",
            fontSize: 17
          }}
        >&gt;</button>
      </div>
      <table style={{
        borderCollapse: "collapse",
        width: "100%",
        maxWidth: 520,
        margin: "0 auto",
        background: "none"
      }}>
        <thead>
          <tr>
            {DAYS.map(day => (
              <th key={day} style={{
                color: theme.accent,
                background: "transparent",
                fontWeight: 800,
                fontSize: 15,
                padding: "7px 0"
              }}>{day}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {grid.map((weekArr, i) => (
            <tr key={i}>
              {weekArr.map(dateObj => {
                const dStr = dateObj.toISOString().split("T")[0];
                const isThisMonth = dateObj.getMonth() === jsMonth;
                const workouts = workoutsByDate[dStr] || [];
                let cellColor = "#282d38";
                if (workouts.length > 0 && isThisMonth) {
                  cellColor = theme.accent;
                }
                return (
                  <td key={dStr} style={{
                    background: isThisMonth ? cellColor : "#191b22",
                    opacity: isThisMonth ? 1 : 0.45,
                    color: isThisMonth && workouts.length > 0 ? "#222" : "#fff",
                    fontWeight: isThisMonth && workouts.length > 0 ? 800 : 400,
                    border: isThisMonth ? `1.5px solid ${theme.thinLine}` : "none",
                    textAlign: "center",
                    height: 46,
                    minWidth: 40,
                    borderRadius: 7,
                    transition: "background .18s"
                  }}>
                    {isThisMonth ? dateObj.getDate() : ""}
                    {workouts.length > 0 && isThisMonth &&
                      <div style={{
                        fontSize: 11,
                        marginTop: 2,
                        color: theme.thinLine,
                        fontWeight: 800
                      }}>
                        {workouts.join(", ")}
                      </div>
                    }
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
      <div style={{
        marginTop: 15,
        textAlign: "center",
        color: "#aaa",
        fontSize: 13,
        fontWeight: 600
      }}>
        Days with a colored background have workouts logged.<br />
        This calendar adapts its colors to your occupational role.
      </div>
    </div>
  );
}
