const BANNER_SPEED = 100; // px per second (tactical, snappy, news-style)

export default function BannerBar({ role = "all" }) {
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;
  const calls = CALLS_FOR_SERVICE[role?.toLowerCase()] || CALLS_FOR_SERVICE.all;

  // Create one long string of all calls, separated by a bullet or dot
  const fullBanner = calls.join("   •   ") + "   •   ";
  const [width, setWidth] = useState(window.innerWidth);

  // For responsive: track window width
  useEffect(() => {
    const handler = () => setWidth(window.innerWidth);
    window.addEventListener("resize", handler);
    return () => window.removeEventListener("resize", handler);
  }, []);

  // Calculate banner pixel length after render
  const scrollRef = useRef();
  const [contentWidth, setContentWidth] = useState(2000);

  useEffect(() => {
    if (scrollRef.current) {
      setContentWidth(scrollRef.current.scrollWidth);
    }
  }, [role, width, fullBanner]);

  // Use a key that resets animation when role changes
  const [key, setKey] = useState(0);
  useEffect(() => { setKey(k => k + 1); }, [role]);

  // Animation duration: scroll from right to left fully
  const duration = contentWidth / BANNER_SPEED;

  return (
    <div style={{
      width: "100%",
      background: theme.widgetBg,
      borderBottom: `5px solid ${theme.thinLine}`,
      overflow: "hidden",
      height: 44,
      position: "relative",
      zIndex: 21,
      boxShadow: "0 2px 14px #000a",
      display: "flex",
      alignItems: "center"
    }}>
      <div style={{
        position: "absolute",
        left: 0,
        top: 0,
        width: "100%",
        height: "100%",
        pointerEvents: "none"
      }}>
        {/* Tactical faint stripes */}
        <svg width="100%" height="100%" style={{ opacity: 0.07 }}>
          <rect x="0" y="0" width="100%" height="100%" fill={theme.thinLine} />
          <rect x="0" y="0" width="100%" height="100%" fill="url(#stripes)" />
          <defs>
            <pattern id="stripes" width="40" height="44" patternUnits="userSpaceOnUse">
              <rect width="15" height="44" fill="#fff" opacity="0.12" />
            </pattern>
          </defs>
        </svg>
      </div>
      <div
        key={key}
        ref={scrollRef}
        style={{
          position: "absolute",
          whiteSpace: "nowrap",
          fontWeight: 900,
          fontSize: 22,
          color: theme.thinLine,
          textShadow: "0 2px 8px #000c",
          letterSpacing: ".09em",
          top: "50%",
          left: 0,
          transform: "translateY(-50%)",
          willChange: "transform",
          animation: `scrollBanner ${duration}s linear infinite`
        }}
      >
        {fullBanner}
        {fullBanner}
      </div>
      <style>
        {`
          @keyframes scrollBanner {
            0% { transform: translateY(-50%) translateX(0); }
            100% { transform: translateY(-50%) translateX(-${contentWidth}px); }
          }
        `}
      </style>
    </div>
  );
}
