// src/components/WaterGoalWidget.jsx
import React, { useState, useEffect } from "react";
import { ROLE_THEMES } from "./roleThemes";

const DEFAULT_GOAL = 100; // ounces

function loadGoal() {
  try {
    const raw = localStorage.getItem("water_goal");
    return raw ? Number(raw) : DEFAULT_GOAL;
  } catch {
    return DEFAULT_GOAL;
  }
}
function saveGoal(goal) {
  localStorage.setItem("water_goal", String(goal));
}

export default function WaterGoalWidget({ role = "all" }) {
  const theme = ROLE_THEMES[role?.toLowerCase()] || ROLE_THEMES.all;
  const [goal, setGoal] = useState(() => loadGoal());
  const [input, setInput] = useState(goal);
  const [message, setMessage] = useState("");

  useEffect(() => { saveGoal(goal); }, [goal]);

  function handleChange(e) {
    setInput(e.target.value.replace(/[^0-9]/g, ""));
  }
  function handleSave(e) {
    e.preventDefault();
    setGoal(Number(input) || DEFAULT_GOAL);
    setMessage("Goal saved!");
    setTimeout(() => setMessage(""), 1200);
  }

  return (
    <div style={{
      background: theme.widgetBg,
      border: `3.5px solid ${theme.thinLine}`,
      borderRadius: 14,
      color: "#fff",
      padding: 20,
      minWidth: 220,
      maxWidth: 320,
      margin: "0 auto 18px auto",
      boxShadow: "0 2px 10px #0006"
    }}>
      <div style={{
        fontWeight: 900,
        fontSize: 20,
        color: theme.thinLine,
        letterSpacing: ".10em",
        marginBottom: 7,
        textAlign: "center"
      }}>
        Water Intake Goal
      </div>
      <form onSubmit={handleSave}>
        <label style={{ color: theme.accent, fontWeight: 800, fontSize: 17 }}>
          Goal (oz):{" "}
          <input
            type="number"
            min={1}
            value={input}
            onChange={handleChange}
            style={{
              width: 70,
              borderRadius: 6,
              border: `2px solid ${theme.thinLine}`,
              background: "#181d21",
              color: "#fff",
              fontWeight: 700,
              fontSize: 17,
              padding: "3px 7px",
              textAlign: "right"
            }}
            required
          />
        </label>
        <button type="submit" style={{
          marginLeft: 10,
          border: "none",
          borderRadius: 8,
          background: theme.thinLine,
          color: "#181d21",
          fontWeight: 900,
          fontSize: 15,
          padding: "6px 16px",
          cursor: "pointer"
        }}>Save</button>
        {message && <div style={{ color: theme.thinLine, fontWeight: 700, marginTop: 8 }}>{message}</div>}
      </form>
    </div>
  );
}
